/**
 * Golden outputs of OSTEP's x86.py: for each run, the FNV-1a hash and line
 * count of everything it prints after the "ARG ..." block with -c. Generated by
 * running `python3 -I <ostep-homework>/threads-{intro,locks}/x86.py -p <prog> <flags> -c`
 * (the counter programs are this page's own, run through threads-locks/x86.py).
 */
export interface Golden {
  dir: 'intro' | 'locks';
  /** Program id in PROGRAMS (or 'counter' / 'counter-tas'). */
  prog: string;
  flags: string;
  hash: string;
  lines: number;
}

